    elif mode is RecognitionPromptMode.READING_V2:
        schema = DrawingReadingV2.model_json_schema(mode="validation")
        # The stored model can validate older offline fixtures without this
        # key, but the provider response must declare its route explicitly.
        schema["required"] = list(
            dict.fromkeys([*schema.get("required", []), "reading_schema_version"])
        )
    elif mode is RecognitionPromptMode.CONCISE:
        schema = ConciseRecognitionOutput.model_json_schema(mode="validation")
    elif mode is RecognitionPromptMode.AUTONOMOUS:
        schema = AutonomousRecognitionOutput.model_json_schema(mode="validation")
    else:
        schema = AgentOneOutput.model_json_schema(mode="validation")
    return _compact_schema(schema) if mode is RecognitionPromptMode.CONCISE else schema

