def _merge_source_conflicts(
    existing: list[dict[str, Any]], detected: list[PassportSourceConflict]
) -> list[dict[str, Any]]:
    """Preserve model carriers; omit only detector copies of the exact sources."""

    def identity(conflict: dict[str, Any]) -> tuple[str, str, tuple[str, ...]]:
        return (
            conflict["field_ref"],
            conflict["kind"],
            tuple(
                sorted(
                    json.dumps(alternative, ensure_ascii=False, sort_keys=True)
                    for alternative in conflict["alternatives"]
                )
            ),
        )

    detected_ids = {conflict.id for conflict in detected}
    # Existing detector copies may already be present after trace binding.
    # Prefer the existing model carrier when these sources now match exactly.
    candidates = [
        *sorted(existing, key=lambda item: item["id"] in detected_ids),
        *(conflict.model_dump(mode="json") for conflict in detected),
    ]
    merged: list[dict[str, Any]] = []
    identities = set()
    ids = set()
    for candidate in candidates:
        key = identity(candidate)
        if key in identities:
            continue
        # A shared generated ID is not evidence of a shared source. Keep both
        # conflicts and preserve the existing model's ID when sources differ.
        suffix = 1
        original_id = candidate["id"]
        while candidate["id"] in ids:
            candidate["id"] = f"{original_id}-detected-{suffix}"
            suffix += 1
        merged.append(candidate)
        ids.add(candidate["id"])
        identities.add(key)
    return merged

