class Feature(ContractModel):
    id: str
    kind: FeatureKind
    raw_text: str
    description: str | None = None
    physical_side: Literal["internal", "external", "unknown"] | None = None
    geometry_role: Literal["surface", "stock", "position", "unknown"] = "surface"
    classification_evidence: EvidenceRef | None = None
    requirement_refs: list[str] = Field(default_factory=list)
    count: int = Field(default=1, ge=1)
    typed_parameters: FeatureParameters | None = None
    dimension_refs: list[str] = Field(default_factory=list)
    context_dimension_refs: list[str] = Field(default_factory=list)
    evidence: EvidenceRef

    @property
    def is_internal(self) -> bool:
        if self.geometry_role != "surface":
            return False
        if self.physical_side is not None:
            return self.physical_side == "internal"
        return self.kind == FeatureKind.HOLE or (
            self.kind == FeatureKind.THREAD
            and isinstance(self.typed_parameters, ThreadParameters)
            and self.typed_parameters.internal_external == "internal"
        )

    @property
    def resolved_side(self) -> str:
        if self.physical_side is not None:
            return self.physical_side
        if self.is_internal:
            return "internal"
        if isinstance(self.typed_parameters, ThreadParameters) and (
            self.typed_parameters.internal_external == "external"
        ):
            return "external"
        return "unknown"

