class EvidenceRef(ContractModel):
    source_region_id: str | None = None
    trace_span_id: str | None = None
    annotation_refs: tuple[str, ...] = ()
    page_no: int | None = Field(default=None, ge=1)
    source_section: SourceSection | None = None
    normalized_bbox: tuple[float, float, float, float] | None = None
    raw_text: str | None = None
    confidence: Decimal | None = Field(default=None, ge=_D_ZERO, le=_D_ONE)
    recognition_status: RecognitionStatus
    verification_status: VerificationStatus = VerificationStatus.UNREVIEWED

    @field_validator("annotation_refs")
    @classmethod
    def unique_annotation_refs(cls, refs: tuple[str, ...]) -> tuple[str, ...]:
        return tuple(dict.fromkeys(refs))

    @field_validator("normalized_bbox")
    @classmethod
    def validate_normalized_bbox(
        cls, value: tuple[float, float, float, float] | None
    ) -> tuple[float, float, float, float] | None:
        if value is None:
            return None
        x0, y0, x1, y1 = value
        if x0 < 0 or y0 < 0 or x1 > 1 or y1 > 1 or x1 <= x0 or y1 <= y0:
            raise ValueError("normalized_bbox must be a positive top-left-origin box inside 0..1")
        return value


class ObservedValue[ValueT](ContractModel):
    value: ValueT | None
    evidence: EvidenceRef

    @field_validator("value")
    @classmethod
    def reject_string_sentinels(cls, value: ValueT | None) -> ValueT | None:
        if isinstance(value, str) and value.strip().casefold() in {"unknown", "n/a", "-"}:
            raise ValueError("unknown values must be null and described by recognition_status")
        return value

    @model_validator(mode="after")
    def keep_value_and_status_consistent(self) -> ObservedValue[ValueT]:
        if self.value is None and self.evidence.recognition_status == RecognitionStatus.OBSERVED:
            raise ValueError("an observed fact must have a value")
        if self.value is not None and self.evidence.recognition_status == RecognitionStatus.MISSING:
            raise ValueError("a missing fact must have a null value")
        return self

