_KIND_LABELS = {
    DimensionKind.LINEAR: "Линейный размер",
    DimensionKind.DIAMETER: "Диаметр (сторона не установлена)",
    DimensionKind.RADIUS: "Радиус",
    DimensionKind.ANGLE: "Угол",
    DimensionKind.THICKNESS: "Толщина",
    DimensionKind.OTHER: "Размер",
}

_HOLE_DIAMETER_LABEL = "Внутренний диаметр"


def _extract_dimension_role_hint(
    dimension: Dimension,
) -> str | None:
    # A feature/relation describes several dimensions; its prose cannot assign the same
    # role to their radius, width, depth and position. Use only this dimension's own data.
    if dimension.role == DimensionRole.POSITION:
        return None
    raw = (dimension.raw_text or "").lower()
    if "фаск" in raw or "x45" in raw or "х45" in raw:
        return "фаска"
    if dimension.role == DimensionRole.OVERALL_LENGTH:
        return "габаритная длина"
    if dimension.role == DimensionRole.OVERALL_WIDTH:
        return "габаритная ширина"
    if dimension.role == DimensionRole.OVERALL_HEIGHT:
        return "габаритная высота"
    if dimension.role == DimensionRole.DEPTH:
        return "глубина"
    if dimension.role == DimensionRole.THICKNESS:
        return "локальная толщина"
    if dimension.role == DimensionRole.SHEET_THICKNESS:
        return "толщина исходного листа"
    if dimension.role == DimensionRole.FLAT_PATTERN_LENGTH:
        return "длина развёртки"
    if dimension.role == DimensionRole.FLAT_PATTERN_WIDTH:
        return "ширина развёртки"
    if dimension.kind == DimensionKind.DIAMETER and re.search(r"[mм]\d+", raw):
        return "диаметр резьбы"

    return None

