# Stored page renders of the recognized drawing: an overview attached to the
# planner request and the full render it may crop. No recognition is re-run.
_DRAWING_IMAGE_KINDS: dict[str, tuple[Literal["overview", "full_resolution"], str | None]] = {
    "whole_page_vision": ("overview", None),
    "source_render": ("full_resolution", "drawing_page{page}_full.png"),
