def drawing_images(runtime, run_id: str) -> tuple[DrawingImage, ...]:
    images = []
    for artifact in runtime.repository.list_artifacts(run_id):
        role = _DRAWING_IMAGE_KINDS.get(artifact.kind)
        if role is None or not artifact.mime_type.startswith("image/"):
            continue
        page = int(artifact.metadata.get("page_no") or 1)
        images.append(
            DrawingImage(
                artifact_id=artifact.id,
                role=role[0],
                page_no=page,
                workspace_file=role[1].format(page=page) if role[1] else None,
                sha256=artifact.sha256,
            )
        )
    # One latest render per role and page.
    latest = {(image.role, image.page_no): image for image in images}
    return tuple(sorted(latest.values(), key=lambda i: (i.page_no, i.role != "overview")))


