    except NoResultFound as error:
        raise _not_found("run", run_id) from error
    passport, snapshot, preview = resolve_blank_preview(run_id, request)
    if _latest_passport(runtime, run_id) != passport:
        raise HTTPException(
            status_code=409, detail="passport changed while reading planning inputs"
        )
    catalog = cast(MachinePassportService, request.app.state.machine_passports).read()
    return RoutePlanningContext(
        passport=passport,
        stock_preview=preview,
        catalog=catalog,
        stock_fingerprint=stock_fingerprint(passport, preview),
        material_basis=route_material_basis(request, preview, snapshot),
        drawing_images=drawing_images(runtime, run_id),
    )

