"""Keep the agent's route; unusable references become visible conditions.

Unknown machines are unassigned rather than guessed, unknown requirement or
feature refs are dropped, and an omitted requirement stays a visible gap.
"""
check_route_structure(proposal)
categories = {c.category_id for c in inputs.catalog.categories}
machines = {m.machine_id: m for m in inputs.catalog.machines}
requirements = {r.id: r for r in inputs.passport.technical_requirements}
# feature_refs name any addressable passport element the operation works on.
passport = inputs.passport
features = {
    item.id
    for item in (
        *passport.features,
        *passport.dimensions,
        *passport.stock_prescriptions,
        *passport.views,
        *passport.local_reference_definitions,
    )
} | {getattr(relation, "id", None) for relation in passport.geometry_relations} - {None}
covered: set[str] = set()
conditions = list(inputs.conditions) + list(proposal.conditions)
operations = []
for op in proposal.operations:
    update: dict[str, object] = {}
    category = op.required_category_id
    machine = machines.get(op.suggested_machine_id or "")
    if op.suggested_machine_id is not None and machine is None:
        conditions.append(
            f"{op.operation_id}: оборудование {op.suggested_machine_id} отсутствует в парке; "
            "назначение снято."
        )
        update["suggested_machine_id"] = None
    if machine is not None and machine.category_id != category:
        # The machine passport defines its category; keep the agent's choice.
        update["required_category_id"] = machine.category_id
    elif category is not None and category not in categories:
        conditions.append(
            f"{op.operation_id}: категория {category} отсутствует в каталоге оборудования."
        )
        update["required_category_id"] = None
    if update.get("suggested_machine_id", op.suggested_machine_id) is None:
        conditions.append(f"{op.operation_id}: оборудование/рабочее место не задано.")
    unknown_refs = [ref for ref in op.requirement_refs if ref not in requirements]
    unknown_features = [ref for ref in op.feature_refs if ref not in features]
    if unknown_refs:
        update["requirement_refs"] = tuple(r for r in op.requirement_refs if r in requirements)
    if unknown_features:
        update["feature_refs"] = tuple(f for f in op.feature_refs if f in features)
    if unknown_refs or unknown_features:
        conditions.append(
            f"{op.operation_id}: отброшены ссылки на отсутствующие в паспорте "
            f"элементы {sorted([*unknown_refs, *unknown_features])}."
        )
    covered.update(r for r in op.requirement_refs if r in requirements)
    # Local operation conditions stay with their operation, not in the route summary.
    operations.append(op.model_copy(update=update) if update else op)

